-- ==============================================================
-- PMS Project: Countries Table with Dial Codes & Digit Rules
-- Ready to import directly into MySQL / phpMyAdmin
-- ==============================================================

-- 1. Ensure table structure exists
CREATE TABLE IF NOT EXISTS `countries` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(191) NOT NULL,
  `phone_code` VARCHAR(10) NULL,
  `iso_code` VARCHAR(10) NULL,
  `min_digits` INT DEFAULT 10,
  `max_digits` INT DEFAULT 10,
  `flag_url` VARCHAR(255) NULL,
  UNIQUE KEY `countries_name_unique` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 2. Ensure columns exist if table was previously created with only (id, name)
SET @dbname = DATABASE();
SET @tablename = 'countries';

SET @sql_phone = (SELECT IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = @dbname AND TABLE_NAME = @tablename AND COLUMN_NAME = 'phone_code') > 0, 'SELECT 1', 'ALTER TABLE `countries` ADD COLUMN `phone_code` VARCHAR(10) NULL AFTER `name`'));
PREPARE stmt_phone FROM @sql_phone; EXECUTE stmt_phone; DEALLOCATE PREPARE stmt_phone;

SET @sql_iso = (SELECT IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = @dbname AND TABLE_NAME = @tablename AND COLUMN_NAME = 'iso_code') > 0, 'SELECT 1', 'ALTER TABLE `countries` ADD COLUMN `iso_code` VARCHAR(10) NULL AFTER `phone_code`'));
PREPARE stmt_iso FROM @sql_iso; EXECUTE stmt_iso; DEALLOCATE PREPARE stmt_iso;

SET @sql_min = (SELECT IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = @dbname AND TABLE_NAME = @tablename AND COLUMN_NAME = 'min_digits') > 0, 'SELECT 1', 'ALTER TABLE `countries` ADD COLUMN `min_digits` INT DEFAULT 10 AFTER `iso_code`'));
PREPARE stmt_min FROM @sql_min; EXECUTE stmt_min; DEALLOCATE PREPARE stmt_min;

SET @sql_max = (SELECT IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = @dbname AND TABLE_NAME = @tablename AND COLUMN_NAME = 'max_digits') > 0, 'SELECT 1', 'ALTER TABLE `countries` ADD COLUMN `max_digits` INT DEFAULT 10 AFTER `min_digits`'));
PREPARE stmt_max FROM @sql_max; EXECUTE stmt_max; DEALLOCATE PREPARE stmt_max;

SET @sql_flag = (SELECT IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = @dbname AND TABLE_NAME = @tablename AND COLUMN_NAME = 'flag_url') > 0, 'SELECT 1', 'ALTER TABLE `countries` ADD COLUMN `flag_url` VARCHAR(255) NULL AFTER `max_digits`'));
PREPARE stmt_flag FROM @sql_flag; EXECUTE stmt_flag; DEALLOCATE PREPARE stmt_flag;

